  ('d2fed9a8-be6a-5f99-b938-b666f42f55b8', null, (select id from public.skills where slug = 'read-g10-authors-purpose'), null, 'hard',
   $q$How does the contrast "A theory can be revised in an afternoon. A missing day of observations can never be recovered." support the author's purpose?$q$, $q$[{"text":"The parallel sentences criticize the volunteers for missing days, which explains why few are remembered.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The parallel sentences stress that recorded data cannot be replaced, which raises the value of the volunteers' work.","is_correct":true},{"text":"The parallel sentences show that modern scientists work faster than the volunteers did in the 1880s.","is_correct":false,"misconception_token":"misreads-comparison"},{"text":"The parallel sentences argue that theories are worthless, which proves that only data matters in science.","is_correct":false,"misconception_token":"overgeneralization"}]$q$::jsonb, $q$The parallel sentences stress that recorded data cannot be replaced, which raises the value of the volunteers' work.$q$, $q$Setting easily revised theories beside data that "can never be recovered" emphasizes why each reading was precious. The author does not call theories worthless; he earlier says "Those people matter."$q$, 'draft', '3afc60df-1469-543f-8804-643b3b3788c0')
